begin;
create temp table fixture(actor uuid default gen_random_uuid(),recruiter uuid default gen_random_uuid(),outsider uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),job uuid default gen_random_uuid(),candidate uuid default gen_random_uuid(),request uuid default gen_random_uuid());
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate<>expected then raise exception 'FAILED wrong SQLSTATE %: % (%)',sqlstate,name,sqlerrm;end if;insert into results values(name,true);return;end;raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,email_confirmed_at,role,aud) select id,id::text||'@age-test.invalid',now(),'authenticated','authenticated' from fixture,lateral unnest(array[actor,recruiter,outsider]) id;
insert into public.companies(id,name) select company,'Age A' from fixture union all select other_company,'Age B' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'owner' from fixture union all select company,recruiter,'recruiter' from fixture union all select other_company,outsider,'owner' from fixture;
insert into public.jobs(id,company_id,titulo,descricao,categoria,criteria) select job,company,'Aprendiz SQL','Aprendizagem em sistemas SQL.','jovem_aprendiz','[{"kind":"skill","text":"SQL","required":true,"weight":5,"min_years":null,"source":null}]' from fixture;
update public.jobs set approved_hash=private.job_hash(private.job_payload(titulo,descricao,categoria,criteria)) where id=(select job from fixture);
insert into public.candidates(id,company_id,processing_status,review_status,dados_extraidos) select candidate,company,'concluido','completed','{"nome_completo":"Data desconhecida","skills":["SQL"]}' from fixture;
insert into public.candidates(company_id,processing_status,review_status,dados_extraidos) select company,'concluido','completed','{"nome_completo":"Faixa especial","skills":["SQL"],"data_nascimento":"1990-01-01"}' from fixture union all select company,'concluido','completed','{"nome_completo":"Ano bissexto","skills":["SQL"],"data_nascimento":"2004-02-29"}'::jsonb from fixture;
select pg_temp.denied('impossible birthday rejected by database',$q$update public.candidates set dados_extraidos='{"data_nascimento":"2023-02-29"}' where id=(select candidate from fixture)$q$,'22008');
select pg_temp.denied('future birthday rejected even through trusted persistence',$q$update public.candidates set dados_extraidos=jsonb_build_object('data_nascimento',((clock_timestamp() at time zone 'America/Sao_Paulo')::date+1)::text) where id=(select candidate from fixture)$q$,'22023');
select pg_temp.ok('unknown date remains null; leap date valid',(select data_nascimento is null from public.candidates where id=(select candidate from fixture)) and (select count(*)=1 from public.candidates where company_id=(select company from fixture) and data_nascimento=date '2004-02-29'));
set local role service_role;
select set_config('test.run',public.begin_ranking(actor,company,job,gen_random_uuid())->>'id',true) from fixture;
select pg_temp.ok('unknown and outside-range candidates all remain in ranking',(select total=3 and eligible=3 from public.ranking_runs where id=current_setting('test.run')::uuid));
select public.stage_ranking((select actor from fixture),current_setting('test.run')::uuid,jsonb_agg(jsonb_build_object('candidate_id',candidate_id,'score',100,'details',jsonb_build_object('formula','evidence-v3')))) from public.ranking_entries where run_id=current_setting('test.run')::uuid;
select public.finish_ranking(actor,current_setting('test.run')::uuid) from fixture;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.denied('legal record requires responsible lawyer and reference',$q$select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,request,0,'legal_recorded','Conferência especial de aprendizagem registrada.',null,null,true) from fixture$q$,'22023');
select pg_temp.denied('review requires explicit confirmation',$q$select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,request,0,'pending_legal','Conferência especial de aprendizagem registrada.',null,null,false) from fixture$q$,'22023');
select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,request,0,'pending_legal','Conferência especial de aprendizagem registrada.',null,null,true) from fixture;
select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,request,0,'pending_legal','Conferência especial de aprendizagem registrada.',null,null,true) from fixture;
select pg_temp.ok('repeated review is idempotent and fully audited',(select count(*)=1 and bool_and(actor_id=(select actor from fixture) and version=1 and status='pending_legal' and candidate_version=0 and review_version=0 and reference_date=(select (created_at at time zone 'America/Sao_Paulo')::date from public.ranking_runs where id=current_setting('test.run')::uuid)) from public.apprentice_case_reviews));
select pg_temp.denied('stale concurrent editor cannot overwrite review',$q$select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,gen_random_uuid(),0,'pending_legal','Outro registro que conflita com o anterior.',null,null,true) from fixture$q$,'40001');
select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,gen_random_uuid(),1,'legal_recorded','Parecer sintético recebido para conferência humana.','Jurídico de teste','Protocolo fictício 0001',true) from fixture;
select pg_temp.ok('legal review preserves previous note and never changes scores',(select count(*)=2 from public.apprentice_case_reviews) and (select count(*)=3 and bool_and(score=100) from public.candidate_scores));
select pg_temp.denied('history cannot be changed directly','update public.apprentice_case_reviews set justification=''forged''','42501');
select pg_temp.denied('history cannot be erased by client','delete from public.apprentice_case_reviews','42501');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',recruiter,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('recruiter does not read restricted case notes',(select count(*)=0 from public.apprentice_case_reviews));
select pg_temp.denied('recruiter cannot review special cases',$q$select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,gen_random_uuid(),2,'pending_legal','Tentativa sem autorização administrativa.',null,null,true) from fixture$q$,'42501');
reset role;
select set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('other company cannot read notes',(select count(*)=0 from public.apprentice_case_reviews));
select pg_temp.denied('company ID cannot be crossed',$q$select public.record_apprentice_review(other_company,current_setting('test.run')::uuid,candidate,gen_random_uuid(),2,'pending_legal','Tentativa de misturar empresas distintas.',null,null,true) from fixture$q$,'42501');
reset role;
update public.candidates set dados_extraidos='{"nome_completo":"Nova leitura","data_nascimento":"2008-01-01"}' where id=(select candidate from fixture);
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.denied('changed curriculum requires new analysis before special review',$q$select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,gen_random_uuid(),2,'pending_legal','Conferência desatualizada de aprendizagem.',null,null,true) from fixture$q$,'40001');
reset role;
delete from public.company_members where user_id=(select actor from fixture);
set local role authenticated;
select pg_temp.ok('revoked administrator cannot read old notes',(select count(*)=0 from public.apprentice_case_reviews));
select pg_temp.denied('revoked administrator cannot reuse completed request',$q$select public.record_apprentice_review(company,current_setting('test.run')::uuid,candidate,request,0,'pending_legal','Conferência especial de aprendizagem registrada.',null,null,true) from fixture$q$,'42501');
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) as results from results;
rollback;
